package org.eclipse.rdf4j.federated.evaluation.join;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;

import org.eclipse.rdf4j.common.iteration.AbstractCloseableIteration;
import org.eclipse.rdf4j.federated.algebra.FedXService;
import org.eclipse.rdf4j.federated.evaluation.FederationEvaluationStrategy;
import org.eclipse.rdf4j.federated.evaluation.concurrent.ParallelExecutor;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.junit.jupiter.api.Test;

class ParallelServiceJoinTaskCloseTest {

	@Test
	void cancellingBlockServiceDrainClosesTheActiveSource() throws Exception {
		FederationEvaluationStrategy strategy = mock(FederationEvaluationStrategy.class);
		FedXService service = mock(FedXService.class);
		List<BindingSet> bindings = List.of(EmptyBindingSet.getInstance());
		@SuppressWarnings("unchecked")
		ParallelExecutor<BindingSet> control = mock(ParallelExecutor.class);
		CountDownLatch started = new CountDownLatch(1);
		CountDownLatch released = new CountDownLatch(1);
		AtomicInteger closeCount = new AtomicInteger();
		AbstractCloseableIteration<BindingSet> source = new AbstractCloseableIteration<>() {
			@Override
			public boolean hasNext() {
				started.countDown();
				try {
					released.await();
				} catch (InterruptedException interrupted) {
					Thread.currentThread().interrupt();
				}
				return false;
			}

			@Override
			public BindingSet next() {
				throw new AssertionError("No row was supplied");
			}

			@Override
			protected void handleClose() {
				closeCount.incrementAndGet();
				released.countDown();
			}
		};
		when(strategy.evaluateService(service, bindings)).thenReturn(source);
		ParallelServiceJoinTask task = new ParallelServiceJoinTask(control, strategy, service, bindings);
		AtomicReference<Throwable> workerFailure = new AtomicReference<>();
		Thread worker = Thread.ofVirtual().start(() -> {
			try (var ignored = task.performTask()) {
			} catch (Throwable failure) {
				workerFailure.set(failure);
			}
		});
		try {
			assertThat(started.await(5, TimeUnit.SECONDS)).isTrue();
			task.cancel();
			assertThat(closeCount).hasValue(1);
		} finally {
			released.countDown();
			worker.join();
		}
		assertThat(workerFailure.get()).isNull();
	}
}
